import{_ as n,o as e,c as r,ai as t}from"./chunks/framework.ampVZV4B.js";const c=JSON.parse('{"title":"Agent 面试 · 高频快答","description":"","frontmatter":{},"headers":[],"relativePath":"guide/agent/quick-qa.md","filePath":"guide/agent/quick-qa.md"}'),l={name:"guide/agent/quick-qa.md"};function o(s,a,i,g,p,h){return e(),r("div",null,[...a[0]||(a[0]=[t(`<h1 id="agent-面试-·-高频快答" tabindex="-1">Agent 面试 · 高频快答 <a class="header-anchor" href="#agent-面试-·-高频快答" aria-label="Permalink to “Agent 面试 · 高频快答”">​</a></h1><blockquote><p><strong>定位：</strong> 面试前 10 分钟速记 + 一面 30～60 秒开口答。<br> 不是 Agent 教程。展开见同目录其它页；项目细节必须换成你自己的真实经历。</p></blockquote><p><strong>面试官其实想确认五件事：</strong><br> 懂 Agent 是什么 → 知道何时该用 → 知道怎么编排 → 出了问题怎么办 → 能把自己的项目讲清楚。</p><hr><h2 id="_1-概念类" tabindex="-1">① 概念类 <a class="header-anchor" href="#_1-概念类" aria-label="Permalink to “① 概念类”">​</a></h2><h3 id="q-agent-是什么" tabindex="-1">Q：Agent 是什么？ <a class="header-anchor" href="#q-agent-是什么" aria-label="Permalink to “Q：Agent 是什么？”">​</a></h3><p><strong>结论：</strong> Agent 是「目标驱动的模型应用」——模型判断下一步做什么，工具真正执行，系统根据结果继续循环，直到完成或触发停止条件。</p><p><strong>三点：</strong></p><ol><li><strong>决策</strong>（下一步干什么）</li><li><strong>工具</strong>（真去执行）</li><li><strong>多步执行</strong>（按结果继续）</li></ol><p><strong>可补一句：</strong> 核心不是「用了大模型」，而是模型参与了任务执行过程中的下一步决策。</p><hr><h3 id="q-agent-和-chatbot-有什么区别" tabindex="-1">Q：Agent 和 Chatbot 有什么区别？ <a class="header-anchor" href="#q-agent-和-chatbot-有什么区别" aria-label="Permalink to “Q：Agent 和 Chatbot 有什么区别？”">​</a></h3><p><strong>结论：</strong> Chatbot 主要解决对话和信息交互；Agent 更强调把事情办完。</p><p><strong>区别不在「更聪明、更会聊」，而在：</strong></p><ol><li>有没有工具调用</li><li>有没有状态 / 多步</li><li>成功标准是「任务完成」还是「答得像」</li></ol><hr><h3 id="q-rag-和-agent-是什么关系" tabindex="-1">Q：RAG 和 Agent 是什么关系？ <a class="header-anchor" href="#q-rag-和-agent-是什么关系" aria-label="Permalink to “Q：RAG 和 Agent 是什么关系？”">​</a></h3><p><strong>结论：</strong> RAG 解决「模型不知道的知识从哪来」；Agent 解决「为了完成任务下一步做什么」。</p><p><strong>可组合：</strong> Agent 可以把检索当成其中一个工具。<br> 知识问答优先 RAG；要调系统、多步办事再上 Agent。</p><hr><h3 id="q-workflow-和-agent-有什么区别" tabindex="-1">Q：Workflow 和 Agent 有什么区别？ <a class="header-anchor" href="#q-workflow-和-agent-有什么区别" aria-label="Permalink to “Q：Workflow 和 Agent 有什么区别？”">​</a></h3><p><strong>结论：</strong> Workflow 是流程基本定死，由代码规定下一步；Agent 是目标定了，中间步骤允许模型根据当前结果动态选。</p><p><strong>选型：</strong></p><ul><li>流程稳定、规则明确 → 优先 Workflow（更稳、更便宜、更好测）</li><li>需要动态决策、工具结果会改变路径 → 再考虑 Agent</li></ul><hr><h3 id="q-为什么需要-agent-什么时候不要上" tabindex="-1">Q：为什么需要 Agent？什么时候不要上？ <a class="header-anchor" href="#q-为什么需要-agent-什么时候不要上" aria-label="Permalink to “Q：为什么需要 Agent？什么时候不要上？”">​</a></h3><p><strong>需要时：</strong> 任务有目标，但中间路径依赖工具结果动态决定；且工具真能帮完成任务。</p><p><strong>不要上时：</strong></p><ol><li>一次问答 / 摘要 / 分类 → 普通模型调用就够</li><li>流程固定、规则明确 → Workflow 更合适</li><li>还没做好超时、重试、幂等、权限、状态恢复、审计 → 别急着做高自主 Agent</li></ol><hr><h3 id="q-要不要微调" tabindex="-1">Q：要不要微调？ <a class="header-anchor" href="#q-要不要微调" aria-label="Permalink to “Q：要不要微调？”">​</a></h3><p><strong>结论：</strong> 一般不一上来就微调。</p><p>先看 Prompt、RAG、工具调用、换模型能不能解决。这些都不够，且有稳定数据和评估集，再考虑微调。多数中小业务用不到先微调。</p><hr><h2 id="_2-工程类" tabindex="-1">② 工程类 <a class="header-anchor" href="#_2-工程类" aria-label="Permalink to “② 工程类”">​</a></h2><blockquote><p>解释框架可以记：<strong>模型 → Agent 编排 → 生产工程</strong>；下面按「编排问题 + 生产问题」开口，不把三层当目录。</p></blockquote><h3 id="q-tool-calling-是什么" tabindex="-1">Q：Tool Calling 是什么？ <a class="header-anchor" href="#q-tool-calling-是什么" aria-label="Permalink to “Q：Tool Calling 是什么？”">​</a></h3><p><strong>结论：</strong> 模型不直接执行工具，而是输出符合 Schema 的调用请求；后端校验参数、执行工具，再把结果返回给模型继续判断。</p><p><strong>要会提的词：</strong> Schema · 参数校验 · 权限 · 超时 · 幂等 · 审计</p><p>展开 → <a href="./tool-calling-interview.html">Tool Calling 面试页</a></p><hr><h3 id="q-agent-为什么需要状态" tabindex="-1">Q：Agent 为什么需要状态？ <a class="header-anchor" href="#q-agent-为什么需要状态" aria-label="Permalink to “Q：Agent 为什么需要状态？”">​</a></h3><p><strong>结论：</strong> Agent 是多步的，后面决策常依赖前面已完成的步骤、工具结果和用户上下文，所以要显式存状态，而不是每步重新猜。</p><p><strong>可提：</strong> 当前目标、已完成步骤、工具结果摘要、失败次数、是否可恢复。</p><hr><h3 id="q-超时、重试、幂等、审计——项目一开始怎么嵌" tabindex="-1">Q：超时、重试、幂等、审计——项目一开始怎么嵌？ <a class="header-anchor" href="#q-超时、重试、幂等、审计——项目一开始怎么嵌" aria-label="Permalink to “Q：超时、重试、幂等、审计——项目一开始怎么嵌？”">​</a></h3><p><strong>结论：</strong> 这四件不是上线前再补的「安全补丁」，是多步 / 多 Agent 流水线 <strong>Day 1 就要进状态机和日志</strong> 的默认项。面试里我会按四句说：</p><ol><li><p><strong>超时</strong><br> 每步 Tool / 模型调用有 deadline，整条流水线有总超时；超时进「失败 / 待重试 / 待人工」，不挂死、不空转烧钱。</p></li><li><p><strong>重试</strong><br> 只对能安全重试的步骤（读 API、检索）；写操作默认不盲目重试，要重试必须先有幂等。</p></li><li><p><strong>幂等</strong><br> 每个会改世界的动作带 <code>idempotencyKey</code>（比如 <code>runId + step</code>）；重复执行不产生第二封邮件、第二条文档、第二笔单。</p></li><li><p><strong>审计</strong><br> 至少记：谁发起、哪个 Agent、调了啥工具、入参出参摘要、耗时、成功/失败、人工有没有确认——出事能回放，不是只看最终答案。</p></li></ol><p><strong>多 Agent 补一句：</strong> 编排 Agent 管总超时和总预算；子 Agent / 每步 Tool 管自己的 deadline；写操作的 key 跨 Agent 也要唯一，避免 A 调过、B 再调又写一遍。</p><p><strong>金句：</strong> Checkpoint 管「执行到哪」，幂等管「再跑一次安不安全」，审计管「谁干的、能不能复查」——三件事别混成一句「我们做了可靠性」。</p><hr><h3 id="q-怎么防止死循环" tabindex="-1">Q：怎么防止死循环？ <a class="header-anchor" href="#q-怎么防止死循环" aria-label="Permalink to “Q：怎么防止死循环？”">​</a></h3><p><strong>结论：</strong> 别指望模型自己停，靠系统设安全边界。</p><p><strong>常用边界：</strong></p><ol><li>最大步数</li><li>总超时</li><li>Token / 成本预算</li><li>连续失败次数 → 熔断或人工接管</li></ol><p>和上面「四件套」一起说更完整：死循环靠步数/预算刹住；单步卡死靠超时；误伤靠幂等和审计兜底。</p><hr><h3 id="q-怎么处理超时和重试" tabindex="-1">Q：怎么处理超时和重试？ <a class="header-anchor" href="#q-怎么处理超时和重试" aria-label="Permalink to “Q：怎么处理超时和重试？”">​</a></h3><p><strong>结论：</strong> 模型调用和工具调用都要有明确超时；重试要限次数，并区分「可重试错误」和「直接失败」。</p><p><strong>开口版：</strong> 读可以重试，写默认不瞎重试；超时不要挂在「调用中」，要进明确状态（失败 / 待重试 / 待人工）。</p><hr><h3 id="q-为什么需要幂等-写操作怎么控制" tabindex="-1">Q：为什么需要幂等？写操作怎么控制？ <a class="header-anchor" href="#q-为什么需要幂等-写操作怎么控制" aria-label="Permalink to “Q：为什么需要幂等？写操作怎么控制？”">​</a></h3><p><strong>结论：</strong> 网络超时再试时，可能第一次其实已经成功，再执行一次会双花、双下单、双发消息——所以写操作要幂等键或去重。</p><p><strong>控制：</strong></p><ul><li>读操作可自动</li><li>删 / 付 / 发 / 改核心数据 → 权限分级，必要时人工确认</li></ul><p><strong>分清两件事：</strong></p><ul><li><strong>Checkpoint</strong> → 执行到哪里了</li><li><strong>幂等</strong> → 这个动作重复执行有没有问题</li></ul><p><strong>可举例：</strong> key 用 <code>runId + step</code>，同一 run 同一布再进一次，业务侧识别为重复请求，直接返回上次结果。</p><hr><h3 id="q-执行到一半失败-服务挂了怎么办" tabindex="-1">Q：执行到一半失败 / 服务挂了怎么办？ <a class="header-anchor" href="#q-执行到一半失败-服务挂了怎么办" aria-label="Permalink to “Q：执行到一半失败 / 服务挂了怎么办？”">​</a></h3><p><strong>结论：</strong> 先分清「从哪恢复」和「重新执行会不会有副作用」。</p><p><strong>常提：</strong> 状态持久化 · Checkpoint · 按失败节点恢复 · 有限 Retry · 幂等 · 人工接管</p><p>展开 → <a href="./reliability-interview.html">可靠性与安全</a></p><hr><h3 id="q-怎么做可观测和审计" tabindex="-1">Q：怎么做可观测和审计？ <a class="header-anchor" href="#q-怎么做可观测和审计" aria-label="Permalink to “Q：怎么做可观测和审计？”">​</a></h3><p><strong>结论：</strong> 至少能看见一次 Agent Run 做了什么，而不只看最终答案。</p><p><strong>建议能查到：</strong> 谁发起、Run ID、哪个 Agent、节点、Tool 调用、参数/结果摘要、模型调用、Token/成本、耗时、错误与重试、人工是否确认。</p><p><strong>开口版：</strong> 审计不是合规口号，是排障和追责的原材料；多 Agent 时更要能回答「这一步是哪个 Agent 调的」。</p><hr><h3 id="q-怎么评价-agent-效果-成本为什么容易失控" tabindex="-1">Q：怎么评价 Agent 效果？成本为什么容易失控？ <a class="header-anchor" href="#q-怎么评价-agent-效果-成本为什么容易失控" aria-label="Permalink to “Q：怎么评价 Agent 效果？成本为什么容易失控？”">​</a></h3><p><strong>效果别只说准确率，至少：</strong></p><ul><li>任务成功率</li><li>人工接管率</li><li>工具调用成功率</li><li>平均步数 / 耗时 / 单任务成本</li><li>失败类型分布</li></ul><p><strong>强调：</strong> 按「任务有没有完成」评，不是只看回答像不像。</p><p><strong>成本：</strong> 多步 × 多工具 × 重试 × 大上下文，费用会指数涨；要用步数/预算上限，能 Workflow 就别全 Agent。</p><hr><h2 id="_3-产品与技术选型类" tabindex="-1">③ 产品与技术选型类 <a class="header-anchor" href="#_3-产品与技术选型类" aria-label="Permalink to “③ 产品与技术选型类”">​</a></h2><h3 id="q-什么时候用-agent-什么时候用-workflow" tabindex="-1">Q：什么时候用 Agent，什么时候用 Workflow？ <a class="header-anchor" href="#q-什么时候用-agent-什么时候用-workflow" aria-label="Permalink to “Q：什么时候用 Agent，什么时候用 Workflow？”">​</a></h3><p><strong>原则：</strong> 能用确定性代码解决的，不要为了「AI 化」硬交给 Agent。</p><ul><li>路径固定 → Workflow</li><li>路径依赖工具结果动态变 → Agent</li><li>只是查知识 → RAG / 普通调用</li></ul><hr><h3 id="q-code-agent-和普通-ai-编程助手有什么区别" tabindex="-1">Q：Code Agent 和普通 AI 编程助手有什么区别？ <a class="header-anchor" href="#q-code-agent-和普通-ai-编程助手有什么区别" aria-label="Permalink to “Q：Code Agent 和普通 AI 编程助手有什么区别？”">​</a></h3><p><strong>结论：</strong> 普通助手偏补全/对话框改片段；Code Agent 更强调读仓、改多文件、跑命令、围绕目标多步推进（如 Cursor Agent、Claude Code）。</p><p>说自己用过什么就说什么，没深度用过的框架别装。</p><hr><h3 id="q-worker-是什么" tabindex="-1">Q：Worker 是什么？ <a class="header-anchor" href="#q-worker-是什么" aria-label="Permalink to “Q：Worker 是什么？”">​</a></h3><p><strong>结论：</strong> Worker 偏「办事」——浏览器、文档、业务系统里的任务交付；和 Code Agent（改代码）不是一类。国内如办公向 Agent，国外如 Operator 一类能力。</p><p>先说清自己做的是 Code 还是 Worker，别混谈。</p><hr><h3 id="q-mcp-是什么" tabindex="-1">Q：MCP 是什么？ <a class="header-anchor" href="#q-mcp-是什么" aria-label="Permalink to “Q：MCP 是什么？”">​</a></h3><p><strong>结论：</strong> 一种让模型侧连接工具/上下文的协议思路（Model Context Protocol）；把它理解成「工具与上下文的连接层」即可。</p><p>没用过就诚实说「了解定位，项目里没用到生产」；别编集成故事。</p><hr><h3 id="q-agent-和普通后端服务最大的工程区别-一个业务为什么不该全部-agent-化" tabindex="-1">Q：Agent 和普通后端服务最大的工程区别？一个业务为什么不该全部 Agent 化？ <a class="header-anchor" href="#q-agent-和普通后端服务最大的工程区别-一个业务为什么不该全部-agent-化" aria-label="Permalink to “Q：Agent 和普通后端服务最大的工程区别？一个业务为什么不该全部 Agent 化？”">​</a></h3><p><strong>区别：</strong> 普通服务路径大多确定；Agent 路径部分由模型动态决定，所以失败模式更杂，更依赖状态、护栏、审计和按任务成功评价。</p><p><strong>不该全 Agent 化：</strong> 稳定规则、强一致写库、高频低成本接口，用确定性服务更合适；Agent 只切在「真有动态决策价值」的切口上。</p><hr><h2 id="_4-项目类" tabindex="-1">④ 项目类 <a class="header-anchor" href="#_4-项目类" aria-label="Permalink to “④ 项目类”">​</a></h2><blockquote><p><strong>不要虚构。</strong> 没有完整自主 Agent，就讲编排 + API + 状态机，别硬贴 Agent 标签。<br> 口述骨架 → <a href="./project-story.html">项目讲述模板</a></p></blockquote><h3 id="q-你做过-agent-吗" tabindex="-1">Q：你做过 Agent 吗？ <a class="header-anchor" href="#q-你做过-agent-吗" aria-label="Permalink to “Q：你做过 Agent 吗？”">​</a></h3><p><strong>答法：</strong> 按真实项目填空——</p><blockquote><p>项目背景 → AI 做什么 → 工具是什么 → 怎么编排 → 状态怎么管 → 为什么这样设计 → 遇到什么问题 → 怎么验证</p></blockquote><p><strong>可结合你经历的诚实口径（示例，面试前改成自己的原话）：</strong></p><ul><li>AI 漫剧 / 生成流水线：多模型 API、异步任务、状态机；若步骤由代码编排为主，就说「工作流 + 模型调用」，有动态决策再称 Agent。</li><li>MES / 业务系统：AI 切口若是助手问答或固定流程，别夸大成全自主 Agent。</li></ul><hr><h3 id="q-为什么这么设计-为什么不用一个-prompt-不用纯-workflow" tabindex="-1">Q：为什么这么设计？为什么不用一个 Prompt / 不用纯 Workflow？ <a class="header-anchor" href="#q-为什么这么设计-为什么不用一个-prompt-不用纯-workflow" aria-label="Permalink to “Q：为什么这么设计？为什么不用一个 Prompt / 不用纯 Workflow？”">​</a></h3><p><strong>开口模板：</strong></p><ul><li>不用单 Prompt：要落库、调外部系统、多步且结果要可恢复</li><li>不用纯 Workflow：某几步路径依赖模型/工具结果才分支（若实际没有，就承认是 Workflow）</li><li>这样设计：可控、可观测、成本和失败可兜底</li></ul><hr><h3 id="q-agent-里有哪些-tool-失败了怎么办" tabindex="-1">Q：Agent 里有哪些 Tool？失败了怎么办？ <a class="header-anchor" href="#q-agent-里有哪些-tool-失败了怎么办" aria-label="Permalink to “Q：Agent 里有哪些 Tool？失败了怎么办？”">​</a></h3><p><strong>Tool：</strong> 只列你项目里真实有的（查库、调生成 API、写任务状态、通知……）。</p><p><strong>失败：</strong> 超时 → 有限重试 → 幂等（写）→ 记失败状态 → 人工/重跑入口。<br> 细节链到工程类同一套答案，别另背一篇。</p><hr><h3 id="q-死循环-执行一半挂了-写操作重复-怎么证明有效" tabindex="-1">Q：死循环 / 执行一半挂了 / 写操作重复 / 怎么证明有效？ <a class="header-anchor" href="#q-死循环-执行一半挂了-写操作重复-怎么证明有效" aria-label="Permalink to “Q：死循环 / 执行一半挂了 / 写操作重复 / 怎么证明有效？”">​</a></h3><p>直接复用工程类口径，用项目里的具体数字或现象举例（步数上限设过多少、有没有重复生成、成功率怎么看）。</p><p><strong>证明有效：</strong> 任务完成率、人工介入次数、耗时/成本对比旧方案——有数据说数据，没有就说「还在用人工抽检 + 失败日志」，别编。</p><hr><h2 id="agent-面试追问链" tabindex="-1">Agent 面试追问链 <a class="header-anchor" href="#agent-面试追问链" aria-label="Permalink to “Agent 面试追问链”">​</a></h2><p>真实一面很少随机跳题，常见是一条链往下追：</p><div class="language-text line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>Agent 是什么？</span></span>
<span class="line"><span>  → 为什么需要 Agent？ / 和 Chatbot 区别？</span></span>
<span class="line"><span>    → 为什么不用 Workflow？ / 什么时候不要上？</span></span>
<span class="line"><span>      → 怎么调用工具？（Tool Calling）</span></span>
<span class="line"><span>        → Tool 失败怎么办？</span></span>
<span class="line"><span>          → 死循环怎么办？</span></span>
<span class="line"><span>            → 执行一半失败怎么办？</span></span>
<span class="line"><span>              → 写操作重复怎么办？（幂等）</span></span>
<span class="line"><span>                → 怎么审计 / 可观测？</span></span>
<span class="line"><span>                  → 这四件事项目一开始怎么嵌的？</span></span>
<span class="line"><span>                    → 怎么评价效果？</span></span>
<span class="line"><span>                      → 结合你的项目讲一遍</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p><strong>复习用法：</strong> 从上到下能不看稿说完；卡在哪一环，就去对应小节页补 5 分钟。</p><hr><h2 id="相关页" tabindex="-1">相关页 <a class="header-anchor" href="#相关页" aria-label="Permalink to “相关页”">​</a></h2><table tabindex="0"><thead><tr><th>需要展开时</th><th>去哪</th></tr></thead><tbody><tr><td>概念边界</td><td><a href="./concepts-interview.html">概念与边界</a></td></tr><tr><td>Tool 设计</td><td><a href="./tool-calling-interview.html">Tool Calling</a></td></tr><tr><td>护栏与翻车</td><td><a href="./reliability-interview.html">可靠性与安全</a></td></tr><tr><td>白板设计</td><td><a href="./scenario-interview.html">场景设计题</a></td></tr><tr><td>产品对比口述</td><td><a href="./compare-interview.html">对比与选型</a></td></tr><tr><td>项目 STAR</td><td><a href="./project-story.html">项目讲述模板</a></td></tr></tbody></table>`,133)])])}const b=n(l,[["render",o]]);export{c as __pageData,b as default};
